// APB Driver - converts sequence items to pin-level APB protocol signals
class apb_driver extends uvm_driver #(apb_seq_item);
  `uvm_component_utils(apb_driver)

  virtual apb_if vif;

  function new(string name = "apb_driver", uvm_component parent = null);
    super.new(name, parent);
  endfunction

  function void build_phase(uvm_phase phase);
    super.build_phase(phase);
    if (!uvm_config_db #(virtual apb_if)::get(this, "", "vif", vif))
      `uvm_fatal(get_type_name(), "Failed to get virtual interface from config_db")
  endfunction

  task run_phase(uvm_phase phase);
    apb_seq_item item;

    // Initialize signals at start
    @(vif.drv_cb);
    vif.drv_cb.PSEL    <= 1'b0;
    vif.drv_cb.PENABLE <= 1'b0;
    vif.drv_cb.PADDR   <= '0;
    vif.drv_cb.PWDATA  <= '0;
    vif.drv_cb.PWRITE  <= 1'b0;

    // Wait for reset deassertion
    wait (vif.PRESETn === 1'b1);
    @(vif.drv_cb);

    forever begin
      seq_item_port.get_next_item(item);
      drive_transaction(item);
      seq_item_port.item_done();
    end
  endtask

  // Drive a single APB transaction following the IDLE→SETUP→ACCESS protocol
  task drive_transaction(apb_seq_item item);
  // SETUP phase
  @(vif.drv_cb);
  vif.drv_cb.PSEL    <= 1'b1;
  vif.drv_cb.PENABLE <= 1'b0;
  vif.drv_cb.PADDR   <= item.addr;
  vif.drv_cb.PWDATA  <= item.wdata;
  vif.drv_cb.PWRITE  <= item.write;

  // ACCESS phase: drive PENABLE high
  @(vif.drv_cb);
  vif.drv_cb.PENABLE <= 1'b1;

  // Wait for PREADY — sample on the *next* clocking event,
  // but don't burn an extra cycle before the first check
  do begin
    @(vif.drv_cb);
  end while (vif.drv_cb.PREADY !== 1'b1);

  // Capture response on the cycle PREADY is high
  item.rdata = vif.drv_cb.PRDATA;
  item.ready = vif.drv_cb.PREADY;
  item.error = vif.drv_cb.PSLVERR;

  // Return to IDLE between transactions
  vif.drv_cb.PSEL    <= 1'b0;
  vif.drv_cb.PENABLE <= 1'b0;
endtask

endclass

