// APB Monitor - samples DUT interface signals independently using mon_cb
class apb_monitor extends uvm_monitor;
  `uvm_component_utils(apb_monitor)

  virtual apb_if vif;
  uvm_analysis_port #(apb_seq_item) ap;

  function new(string name = "apb_monitor", uvm_component parent = null);
    super.new(name, parent);
  endfunction

  function void build_phase(uvm_phase phase);
    super.build_phase(phase);
    ap = new("ap", this);
    if (!uvm_config_db #(virtual apb_if)::get(this, "", "vif", vif))
      `uvm_fatal(get_type_name(), "Failed to get virtual interface from config_db")
  endfunction

  task run_phase(uvm_phase phase);
    apb_seq_item item;

    // Wait for reset deassertion
    wait (vif.PRESETn === 1'b1);

    forever begin
      @(vif.mon_cb);

      // Detect a completed transaction: PSEL=1, PENABLE=1, PREADY=1
      if (vif.mon_cb.PSEL && vif.mon_cb.PENABLE && vif.mon_cb.PREADY) begin
        item = apb_seq_item::type_id::create("mon_item");
        item.addr   = vif.mon_cb.PADDR;
        item.wdata  = vif.mon_cb.PWDATA;
        item.write  = vif.mon_cb.PWRITE;
        item.rdata  = vif.mon_cb.PRDATA;
        item.ready  = vif.mon_cb.PREADY;
        item.error  = vif.mon_cb.PSLVERR;

        `uvm_info(get_type_name(), $sformatf("Monitored: %s addr=0x%0h wdata=0x%0h rdata=0x%0h err=%0b",
                  item.write ? "WRITE" : "READ", item.addr, item.wdata, item.rdata, item.error), UVM_HIGH)

        ap.write(item);
      end
    end
  endtask

endclass

