// APB Scoreboard with reference memory model
class apb_scoreboard extends uvm_scoreboard;
  `uvm_component_utils(apb_scoreboard)

  uvm_analysis_imp #(apb_seq_item, apb_scoreboard) ap_imp;

  // Reference memory model - mirrors DUT memory
  logic [31:0] ref_mem [32];

  // Statistics
  int unsigned write_count;
  int unsigned read_count;
  int unsigned error_count;
  int unsigned pass_count;
  int unsigned fail_count;

  function new(string name = "apb_scoreboard", uvm_component parent = null);
    super.new(name, parent);
  endfunction

  function void build_phase(uvm_phase phase);
    super.build_phase(phase);
    ap_imp = new("ap_imp", this);

    // Initialize reference memory to zero (matches RTL reset)
    for (int i = 0; i < 32; i++)
      ref_mem[i] = '0;

    write_count = 0;
    read_count  = 0;
    error_count = 0;
    pass_count  = 0;
    fail_count  = 0;
  endfunction

  function void write(apb_seq_item item);
    bit addr_oor = item.addr[5]; // Out-of-range flag

    // Check 1: Error response for out-of-range address
    if (addr_oor) begin
      error_count++;
      if (item.error !== 1'b1) begin
        `uvm_error(get_type_name(),
          $sformatf("FAIL: OOR addr=0x%0h expected PSLVERR=1, got PSLVERR=%0b",
                    item.addr, item.error))
        fail_count++;
      end else begin
        `uvm_info(get_type_name(),
          $sformatf("PASS: OOR addr=0x%0h correctly returned PSLVERR=1", item.addr), UVM_HIGH)
        pass_count++;
      end
      return; // No memory update for OOR
    end

    // Check 2: No error for valid address
    if (item.error !== 1'b0) begin
      `uvm_error(get_type_name(),
        $sformatf("FAIL: Valid addr=0x%0h got unexpected PSLVERR=1", item.addr))
      fail_count++;
      return;
    end

    if (item.write) begin
      // Write transaction - update reference model
      write_count++;
      ref_mem[item.addr[4:0]] = item.wdata;
      `uvm_info(get_type_name(),
        $sformatf("PASS: Write addr=0x%0h data=0x%0h", item.addr, item.wdata), UVM_HIGH)
      pass_count++;
    end else begin
      // Read transaction - compare against reference model
      read_count++;
      if (item.rdata !== ref_mem[item.addr[4:0]]) begin
        `uvm_error(get_type_name(),
          $sformatf("FAIL: Read addr=0x%0h expected=0x%0h actual=0x%0h",
                    item.addr, ref_mem[item.addr[4:0]], item.rdata))
        fail_count++;
      end else begin
        `uvm_info(get_type_name(),
          $sformatf("PASS: Read addr=0x%0h data=0x%0h matches reference",
                    item.addr, item.rdata), UVM_HIGH)
        pass_count++;
      end
    end
  endfunction

  function void report_phase(uvm_phase phase);
    super.report_phase(phase);
    `uvm_info(get_type_name(), "========== SCOREBOARD REPORT ==========", UVM_LOW)
    `uvm_info(get_type_name(), $sformatf("  Writes:     %0d", write_count), UVM_LOW)
    `uvm_info(get_type_name(), $sformatf("  Reads:      %0d", read_count), UVM_LOW)
    `uvm_info(get_type_name(), $sformatf("  Errors:     %0d", error_count), UVM_LOW)
    `uvm_info(get_type_name(), $sformatf("  PASS:       %0d", pass_count), UVM_LOW)
    `uvm_info(get_type_name(), $sformatf("  FAIL:       %0d", fail_count), UVM_LOW)
    `uvm_info(get_type_name(), "========================================", UVM_LOW)
    if (fail_count > 0)
      `uvm_error(get_type_name(), $sformatf("TEST FAILED with %0d errors", fail_count))
    else
      `uvm_info(get_type_name(), "TEST PASSED - All checks passed", UVM_LOW)
  endfunction

endclass

