// APB Functional Coverage Subscriber
class apb_coverage extends uvm_subscriber #(apb_seq_item);
  `uvm_component_utils(apb_coverage)

  // Covergroup for APB transaction coverage
  // Uses sample-with-argument so coverpoint expressions are resolved
  // against the item passed in, not a class member that may be null
  // at construction time.
  covergroup apb_cg with function sample(apb_seq_item txn);
option.per_instance = 1;

    // Direction coverage
    cp_write: coverpoint txn.write {
      bins write = {1};
      bins read  = {0};
    }

    // Address coverage - specifically PADDR[4:0] for valid addresses
    cp_addr_lo: coverpoint txn.addr[4:0] {
      bins addr_zero  = {0};
      bins addr_low   = {[1:7]};
      bins addr_mid   = {[8:23]};
      bins addr_high  = {[24:30]};
      bins addr_max   = {31};
    }

    // Out-of-range address bit
    cp_addr_oor: coverpoint txn.addr[5] {
      bins valid   = {0};
      bins invalid = {1};
    }

    // Write data coverage
    cp_wdata: coverpoint txn.wdata {
      bins zero      = {32'h00000000};
      bins max_val   = {32'hFFFFFFFF};
      bins low_range = {[32'h00000001:32'h0000FFFF]};
      bins mid_range = {[32'h00010000:32'h7FFFFFFF]};
      bins hi_range  = {[32'h80000000:32'hFFFFFFFE]};
    }

    // Error response coverage
    cp_error: coverpoint txn.error {
      bins no_error = {0};
      bins error    = {1};
    }

    // Cross: direction x address validity
    cx_dir_oor: cross cp_write, cp_addr_oor {
      bins write_valid   = binsof(cp_write.write) && binsof(cp_addr_oor.valid);
      bins write_invalid = binsof(cp_write.write) && binsof(cp_addr_oor.invalid);
      bins read_valid    = binsof(cp_write.read)  && binsof(cp_addr_oor.valid);
      bins read_invalid  = binsof(cp_write.read)  && binsof(cp_addr_oor.invalid);
    }

    // Cross: direction x error
    cx_dir_err: cross cp_write, cp_error;

    // Cross: direction x address range (valid only)
    cx_dir_addr: cross cp_write, cp_addr_lo;

    // Cross: address validity x error response
    cx_oor_err: cross cp_addr_oor, cp_error {
      bins valid_no_err   = binsof(cp_addr_oor.valid)   && binsof(cp_error.no_error);
      bins invalid_err    = binsof(cp_addr_oor.invalid) && binsof(cp_error.error);
      // These would be protocol violations:
      illegal_bins valid_err      = binsof(cp_addr_oor.valid)   && binsof(cp_error.error);
      illegal_bins invalid_no_err = binsof(cp_addr_oor.invalid) && binsof(cp_error.no_error);
    }

  endgroup

  function new(string name = "apb_coverage", uvm_component parent = null);
    super.new(name, parent);
    apb_cg = new();
  endfunction

  function void write(apb_seq_item t);
  apb_cg.sample(t);
  //`uvm_info(get_type_name(), "OPTION_A_LIVE", UVM_LOW)
endfunction

  function void report_phase(uvm_phase phase);
  super.report_phase(phase);
  `uvm_info(get_type_name(),
    $sformatf("type_cov=%.2f  inst_cov=%.2f  cp_write=%.1f  cp_addr_oor=%.1f",
              apb_cg.get_coverage(),
              apb_cg.get_inst_coverage(),
              apb_cg.cp_write.get_coverage(),
              apb_cg.cp_addr_oor.get_coverage()),
    UVM_LOW)
endfunction

endclass

