  function void build_phase(uvm_phase phase);
    super.build_phase(phase);

    // Monitor is always instantiated
    mon = apb_monitor::type_id::create("mon", this);

    // Driver and sequencer only in ACTIVE mode
    if (get_is_active() == UVM_ACTIVE) begin
      drv = apb_driver::type_id::create("drv", this);
      sqr = apb_sequencer::type_id::create("sqr", this);
    end
  endfunction

  function void connect_phase(uvm_phase phase);
    super.connect_phase(phase);

    // Connect driver to sequencer in ACTIVE mode
    if (get_is_active() == UVM_ACTIVE) begin
      drv.seq_item_port.connect(sqr.seq_item_export);
    end

    // Expose monitor's analysis port at agent level
    ap = mon.ap;
  endfunction

endclass

// ════════════════════════════════════════════════════════════
// Environment (uvm_env)
// ════════════════════════════════════════════════════════════

// APB Environment - instantiates agent, scoreboard, and coverage
class apb_env extends uvm_env;
  `uvm_component_utils(apb_env)

  apb_agent      agent;
  apb_scoreboard scoreboard;
  apb_coverage   coverage;

  function new(string name = "apb_env", uvm_component parent = null);
    super.new(name, parent);
  endfunction

  function void build_phase(uvm_phase phase);
    super.build_phase(phase);

    agent      = apb_agent::type_id::create("agent", this);
    scoreboard = apb_scoreboard::type_id::create("scoreboard", this);
    coverage   = apb_coverage::type_id::create("coverage", this);
  endfunction

  function void connect_phase(uvm_phase phase);
    super.connect_phase(phase);

    // Connect monitor analysis port to scoreboard and coverage
    agent.ap.connect(scoreboard.ap_imp);
    agent.ap.connect(coverage.analysis_export);
  endfunction

endclass

// ════════════════════════════════════════════════════════════
// Test (uvm_test)
// ════════════════════════════════════════════════════════════

// APB Test - top-level UVM test
class apb_test extends uvm_test;
  `uvm_component_utils(apb_test)

  apb_env env;

  function new(string name = "apb_test", uvm_component parent = null);
    super.new(name, parent);
  endfunction

  function void build_phase(uvm_phase phase);
    super.build_phase(phase);
    env = apb_env::type_id::create("env", this);
  endfunction

  task run_phase(uvm_phase phase);
    apb_master_sequence master_seq;

    phase.raise_objection(this, "Starting APB test");

    master_seq = apb_master_sequence::type_id::create("master_seq");
    master_seq.start(env.agent.sqr);

    // Allow drain time for any remaining transactions
    #100;

    phase.drop_objection(this, "APB test complete");
  endtask

  function void report_phase(uvm_phase phase);
    uvm_report_server svr;
    super.report_phase(phase);
    svr = uvm_report_server::get_server();
    if (svr.get_severity_count(UVM_FATAL) + svr.get_severity_count(UVM_ERROR) > 0)
      `uvm_info(get_type_name(), "===== TEST FAILED =====", UVM_NONE)
    else
      `uvm_info(get_type_name(), "===== TEST PASSED =====", UVM_NONE)
  endfunction

endclass

// ════════════════════════════════════════════════════════════
// UVM Top (tb_top)
// ════════════════════════════════════════════════════════════

// =============================================================================
// TB Top - instantiates DUT, interface, generates clock/reset, calls run_test()
// =============================================================================

module tb_top;

  // Clock generation
  logic PCLK;
  initial begin
    PCLK = 0;
    forever #5 PCLK = ~PCLK; // 100MHz clock (10ns period)
  end

  // Instantiate the APB interface
  apb_if apb_vif(.PCLK(PCLK));

  // Instantiate the DUT and connect via interface
  apb_memory dut (
    .PCLK    (PCLK),
    .PRESETn (apb_vif.PRESETn),
    .PADDR   (apb_vif.PADDR),
    .PWDATA  (apb_vif.PWDATA),
    .PSEL    (apb_vif.PSEL),
    .PENABLE (apb_vif.PENABLE),
    .PWRITE  (apb_vif.PWRITE),
    .PRDATA  (apb_vif.PRDATA),
    .PREADY  (apb_vif.PREADY),
    .PSLVERR (apb_vif.PSLVERR)
  );

  // Connect DUT outputs back to interface (they are already connected above,
  // but we need to ensure bidirectional connectivity for monitor)
  // Since PRDATA, PREADY, PSLVERR are outputs from DUT connected to interface
  // wires, the monitor can read them directly.

  // Reset generation
  initial begin
    apb_vif.PRESETn = 1'b0;
    apb_vif.PSEL    = 1'b0;
    apb_vif.PENABLE = 1'b0;
    apb_vif.PADDR   = '0;
    apb_vif.PWDATA  = '0;
    apb_vif.PWRITE  = 1'b0;

    // Hold reset for 5 clock cycles
    repeat (5) @(posedge PCLK);
    apb_vif.PRESETn = 1'b1;
    `uvm_info("TB_TOP", "Reset deasserted", UVM_LOW)
  end

  // Store virtual interface in config_db and start test
  initial begin
    uvm_config_db #(virtual apb_if)::set(null, "*", "vif", apb_vif);
uvm_top.set_timeout(10ms, 0);
    run_test("apb_test");
  end

  // Timeout watchdog
  initial begin
    #1000000;
    `uvm_fatal("TB_TOP", "Simulation timeout!")
  end

  // Dump waveforms (optional, simulator-dependent)
  initial begin
    $dumpfile("apb_tb.vcd");
    $dumpvars(0, tb_top);
  end

endmodule

